data.minimal_example:
final SecureBookmarks secureBookmarks = SecureBookmarks();
final SecureBookmarkMint mint = await secureBookmarks.mint(File('/path/to/file'));

// Later, resolve to access:
final SecureBookmarkResolution resolution = await secureBookmarks.resolve(
  id: 'my-doc',
  bookmarkBytes: mint.bookmark,
);
// Access file at resolution.path, then release:
await secureBookmarks.release('my-doc');
